package org.humanjourney.core.geography;
import java.util.*;
import com.google.gson.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.humanjourney.core.mapfeature.FeatureGeometry;
import org.humanjourney.core.water.WaterGeography.Point;
import org.humanjourney.core.npc.context.*;
public class GeographyV2Test {
 public static final String DIM="minecraft:overworld";
 public static List<Point> circle(int n,double x,double z,double r){var points=new ArrayList<Point>();for(int i=0;i<n;i++){double a=i*2*Math.PI/n;points.add(new Point(x+r*Math.cos(a),z+r*Math.sin(a)));}return points;}
 public static JsonArray points(List<Point> points){var out=new JsonArray();for(var p:points){var a=new JsonArray();a.add(p.x());a.add(p.z());out.add(a);}return out;}
 public static JsonObject part(int points,double x,double z,double radius){var o=new JsonObject();o.add("outer",points(circle(points,x,z,radius)));return o;}
 public static JsonObject geometry(int parts){var g=new JsonObject();if(parts==1){g.addProperty("type","polygon");g.add("outer",points(circle(4,0,0,100)));var holes=new JsonArray();holes.add(points(circle(4,0,0,20)));g.add("holes",holes);}else{g.addProperty("type","multipolygon");var p=new JsonArray();for(int i=0;i<parts;i++)p.add(part(32,i*300,0,100));g.add("polygons",p);}return g;}
 public static JsonObject resource(int version,String id,boolean local,JsonObject geometry){var root=new JsonObject();root.addProperty("schema_version",version);var a=new JsonObject();a.addProperty("id",id);a.addProperty("display_label","Label "+id);if(version==1)a.add("polygon",points(circle(4,0,0,100)));else a.add("geometry",geometry);var list=new JsonArray();list.add(a);root.add(local?"local_areas":"macro_regions",list);return root;}
 public static NpcGeography parse(JsonElement... roots){return NpcGeography.parse(List.of(roots),Set.of("era_0","era_1"));}
 @Test void v1AndV2CoexistAndV1LimitRemains256(){var old=resource(1,"macro",false,null);var modern=resource(2,"local",true,geometry(1));var geo=parse(old,modern);assertEquals("macro",geo.resolve(DIM,50,0,"era_0").macro());assertEquals("local",geo.resolve(DIM,50,0,"era_0").local());old.getAsJsonArray("macro_regions").get(0).getAsJsonObject().add("polygon",points(circle(257,0,0,100)));assertThrows(RuntimeException.class,()->parse(old));}
 @Test void holeInteriorAndEdgesAreExcludedOuterEdgeInclusive(){var geo=parse(resource(2,"local",true,geometry(1)));for(double x:new double[]{0,10,20})assertEquals("none",geo.resolve(DIM,x,0,"era_0").local());assertEquals("local",geo.resolve(DIM,100,0,"era_0").local());}
 @Test void disconnectedComponentsShareIdentityAndDoNotIndexGap(){var geo=parse(resource(2,"archipelago",true,geometry(2)));assertEquals("archipelago",geo.resolve(DIM,0,0,"era_0").local());assertEquals("archipelago",geo.resolve(DIM,300,0,"era_0").local());assertEquals("none",geo.resolve(DIM,150,0,"era_0").local());assertEquals(0,geo.candidateCount(DIM,150,0));assertEquals(1,geo.candidateCount(DIM,300,0));}
 @Test void sameAreaOverlappingPartsDoNotBecomePriorityAmbiguity(){var g=geometry(2);var p=g.getAsJsonArray("polygons");p.set(1,p.get(0).deepCopy());assertEquals("local",parse(resource(2,"local",true,g)).resolve(DIM,0,0,"era_0").local());}
 @Test void localPriorityAndDistinctTiesRemainUnchanged(){var a=resource(1,"a",true,null);var b=resource(1,"b",true,null);assertThrows(RuntimeException.class,()->parse(a,b).resolve(DIM,0,0,"era_0"));b.getAsJsonArray("local_areas").get(0).getAsJsonObject().addProperty("priority",10);assertEquals("b",parse(a,b).resolve(DIM,0,0,"era_0").local());}
 @Test void parentFallbackConflictAndDimensionValidationRemain(){var macro=resource(1,"macro",false,null);var local=resource(2,"local",true,geometry(2));local.getAsJsonArray("local_areas").get(0).getAsJsonObject().addProperty("macro_region","macro");var geo=parse(macro,local);assertEquals("macro",geo.resolve(DIM,300,0,"era_0").macro());var other=resource(1,"other",false,null);other.getAsJsonArray("macro_regions").get(0).getAsJsonObject().addProperty("priority",20);assertThrows(RuntimeException.class,()->parse(macro,other,local).resolve(DIM,50,0,"era_0"));macro.getAsJsonArray("macro_regions").get(0).getAsJsonObject().addProperty("dimension","minecraft:the_nether");assertThrows(RuntimeException.class,()->parse(macro,local));}
 @Test void profilesAndEraLabelsUseStableIdMaps(){var local=resource(2,"local",true,geometry(1));var a=local.getAsJsonArray("local_areas").get(0).getAsJsonObject();a.add("era_labels",JsonParser.parseString("{\"era_0\":\"Old Label\"}"));a.add("profile",JsonParser.parseString("{\"temperature\":[\"cool\"],\"moisture\":[\"dry\"],\"vegetation\":[\"grassland\"],\"water\":[\"inland\"],\"relief\":[\"plain\"],\"special\":[]}"));var geo=parse(local);assertEquals("Old Label",geo.resolve(DIM,50,0,"era_0").label());assertEquals(geo.localIds().get("local").profile(),geo.profile("none","local"));assertThrows(UnsupportedOperationException.class,()->geo.localIds().clear());}
 @Test void sharedDiscoveryStableAcrossMigrationAndStaleIdsRemain(){var ledger=new DiscoveryLedger();ledger.mark(DiscoveryLedger.Kind.MACRO,"macro");ledger.mark(DiscoveryLedger.Kind.LOCAL,"local");var before=ledger.snapshot();var geo=parse(resource(2,"macro",false,geometry(1)),resource(2,"local",true,geometry(2)));assertEquals(2,new org.humanjourney.core.geography.map.MapProjection.Factory(geo,"era_0").project(before).areas().size());assertEquals(before,ledger.snapshot());assertEquals(1,new org.humanjourney.core.geography.map.MapProjection.Factory(parse(resource(1,"macro",false,null)),"era_0").project(before).staleLocals());}
 @Test void exact4096Vertices128PartsAcceptedAndOneAboveEitherRejects(){var g=geometry(128);var geo=parse(resource(2,"max",true,g));assertEquals(4096,geo.localIds().get("max").shape().vertexCount());assertEquals(128,geo.localIds().get("max").shape().ringCount());g.getAsJsonArray("polygons").add(part(3,40000,0,100));assertThrows(RuntimeException.class,()->parse(resource(2,"bad",true,g)));g.getAsJsonArray("polygons").remove(128);g.getAsJsonArray("polygons").get(0).getAsJsonObject().getAsJsonArray("outer").add(JsonParser.parseString("[110,110]"));assertThrows(RuntimeException.class,()->parse(resource(2,"bad",true,g)));}
 @Test void maximumManyHolePolygonUsesSameProvenTopology(){var g=new JsonObject();g.addProperty("type","polygon");g.add("outer",points(circle(32,0,0,5000)));var holes=new JsonArray();for(int i=0;i<127;i++)holes.add(points(circle(32,i%12*30,i/12*30,5)));g.add("holes",holes);var geo=parse(resource(2,"holes",true,g));assertEquals(4096,geo.localIds().get("holes").shape().vertexCount());assertEquals("none",geo.resolve(DIM,0,0,"era_0").local());}
 @Test void malformedTopologyAndMixedSchemaFieldsRejectWithAreaContext(){for(String invalid:List.of("{\"type\":\"multipolygon\",\"polygons\":[]}","{\"type\":\"polygon\",\"outer\":[[0,0],[100,100],[0,100],[100,0]]}","{\"type\":\"polyline\",\"points\":[[0,0],[1,1]]}","{\"type\":\"polygon\",\"outer\":[[0,0],[100,0],[100,100],[0,100]],\"holes\":[[[0,10],[20,10],[20,20],[0,20]]]}","{\"type\":\"polygon\",\"outer\":[[0,0],[100,0],[100,100],[0,100]],\"holes\":[[[10,10],[90,10],[90,90],[10,90]],[[20,20],[30,20],[30,30],[20,30]]] }")){var error=assertThrows(RuntimeException.class,()->parse(resource(2,"bad_area",true,JsonParser.parseString(invalid).getAsJsonObject())));assertTrue(error.getMessage().contains("bad_area"));}var old=resource(1,"old",true,null);old.getAsJsonArray("local_areas").get(0).getAsJsonObject().add("geometry",geometry(1));assertThrows(RuntimeException.class,()->parse(old));}
 @Test void aggregateQuotaAllowsTheoreticalV1MaximumButRejectsV2Overflow(){var shape=FeatureGeometry.polygon(new FeatureGeometry.Part(new FeatureGeometry.Ring(circle(256,0,0,100)),List.of()));var macros=new ArrayList<NpcGeography.Area>();var locals=new ArrayList<NpcGeography.Area>();for(int i=0;i<512;i++)macros.add(new NpcGeography.Area("m_"+i,DIM,i,"none","M",Map.of(),shape,null));for(int i=0;i<4096;i++)locals.add(new NpcGeography.Area("l_"+i,DIM,i,"none","L",Map.of(),shape,null));assertDoesNotThrow(()->new NpcGeography(macros,locals));var maximum=FeatureGeometry.multipolygon(java.util.stream.IntStream.range(0,128).mapToObj(i->new FeatureGeometry.Part(new FeatureGeometry.Ring(circle(32,i*300,0,10)),List.of())).toList());var shapes=new ArrayList<FeatureGeometry>(Collections.nCopies(288,maximum));assertDoesNotThrow(()->GeographyGeometry.catalog(shapes));shapes.add(maximum);assertThrows(RuntimeException.class,()->GeographyGeometry.catalog(shapes));var ringHeavy=FeatureGeometry.multipolygon(Collections.nCopies(128,new FeatureGeometry.Part(new FeatureGeometry.Ring(circle(3,0,0,10)),List.of())));assertThrows(RuntimeException.class,()->GeographyGeometry.catalog(Collections.nCopies(513,ringHeavy)));}
 @Test void distributed1500And4096LocalsOnlyTestNearbyCandidates(){for(int count:List.of(1500,4096)){var areas=new ArrayList<NpcGeography.Area>();for(int i=0;i<count;i++)areas.add(new NpcGeography.Area("l_"+i,DIM,0,"none","Local",Map.of(),FeatureGeometry.polygon(new FeatureGeometry.Part(new FeatureGeometry.Ring(circle(4,i*300,0,100)),List.of())),null));var geo=new NpcGeography(List.of(),areas);assertEquals(1,geo.candidateCount(DIM,300,0));assertEquals("l_1",geo.resolve(DIM,300,0,"era_0").local());assertEquals(0,geo.candidateCount(DIM,150,0));}}
 @Test void indexedResolverMatchesLegacyV1LoopAtBoundariesAndOutside(){var areas=new ArrayList<NpcGeography.Area>();for(int i=0;i<100;i++)areas.add(new NpcGeography.Area("l_"+i,DIM,i,"none","Local",Map.of(),FeatureGeometry.polygon(new FeatureGeometry.Part(new FeatureGeometry.Ring(circle(4,i*100,0,80)),List.of())),null));var geo=new NpcGeography(List.of(),areas);for(int x=-100;x<10200;x+=7){final int px=x;var best=areas.stream().filter(a->a.shape().contains(px,0)).max(Comparator.comparingInt(NpcGeography.Area::priority));assertEquals(best.map(NpcGeography.Area::id).orElse("none"),geo.resolve(DIM,x,0,"era_0").local());}}
 @Test void unknownParentErrorNamesResourcePackAndArea(){var local=resource(2,"test_local",true,geometry(1));local.getAsJsonArray("local_areas").get(0).getAsJsonObject().addProperty("macro_region","missing");var error=assertThrows(RuntimeException.class,()->NpcGeography.parse(List.of(local),Set.of("era_0"),org.humanjourney.core.npc.economy.GeoProfile.vocabulary(null),List.of("test:fixture [synthetic-pack]")));assertTrue(error.getMessage().contains("test:fixture [synthetic-pack]"));assertTrue(error.getMessage().contains("test_local"));assertTrue(error.getMessage().contains("missing"));}
}
